<?php

use Saad\AiKit\Rag\Text\ArabicNormalizer;

/*
 * The fixture was GENERATED by running catodemy's own SearchQueryText /
 * ArabicText (origin/main fc11c288) over these inputs, and the TypeScript twin
 * (js/rag/normalize.test.ts) asserts the same file — so kit PHP, kit TS and
 * the indexes catodemy already built all fold identically.
 */
function normalizerFixture(): array
{
    return json_decode((string) file_get_contents(__DIR__.'/../../Fixtures/rag/normalize.json'), true, flags: JSON_THROW_ON_ERROR);
}

it('spells the translate() constants byte-for-byte as the index was built with', function () {
    $constants = normalizerFixture()['constants'];

    expect(ArabicNormalizer::MARKS)->toBe($constants['marks'])
        ->and(ArabicNormalizer::FOLD_FROM)->toBe($constants['fold_from'])
        ->and(ArabicNormalizer::FOLD_TO)->toBe($constants['fold_to'])
        ->and(ArabicNormalizer::DIGITS_FROM)->toBe($constants['digits_from'])
        ->and(ArabicNormalizer::DIGITS_TO)->toBe($constants['digits_to'])
        ->and(ArabicNormalizer::TRANSLATE_FROM)->toBe($constants['translate_from'])
        ->and(ArabicNormalizer::TRANSLATE_TO)->toBe($constants['translate_to']);
});

it('matches the shared fixture case by case', function (array $case) {
    expect(ArabicNormalizer::canonicalize($case['input']))->toBe($case['canonicalize'])
        ->and(ArabicNormalizer::normalize($case['input']))->toBe($case['normalize'])
        ->and(ArabicNormalizer::normalizeLower($case['input']))->toBe($case['normalize_lower'])
        ->and(ArabicNormalizer::tokens($case['input']))->toBe($case['tokens']);
})->with(function () {
    foreach (normalizerFixture()['cases'] as $case) {
        yield $case['note'] => [$case];
    }
});

it('is idempotent', function () {
    foreach (normalizerFixture()['cases'] as $case) {
        $once = ArabicNormalizer::normalize($case['input']);

        expect(ArabicNormalizer::normalize($once))->toBe($once)
            ->and(ArabicNormalizer::canonicalize(ArabicNormalizer::canonicalize($case['input'])))
            ->toBe(ArabicNormalizer::canonicalize($case['input']));
    }
});

it('folds 1:1 after the marks are stripped, so positions map back', function () {
    $stripped = ArabicNormalizer::stripMarks('مُحاضَرة ١٤٤٤ مسئولية');

    expect(mb_strlen(ArabicNormalizer::normalizeDigits(ArabicNormalizer::foldOrthography($stripped))))
        ->toBe(mb_strlen($stripped));
});

it('builds the translate() SQL expression from the one constant pair', function () {
    expect(ArabicNormalizer::translateSql('lower(title)'))
        ->toBe("translate(lower(title), '".ArabicNormalizer::TRANSLATE_FROM."', '".ArabicNormalizer::TRANSLATE_TO."')");
});
